def parse_rows():
    rows = []
    for n, line in enumerate(RAW.strip().split("\n"), 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split("|")
        if len(parts) != 7:
            raise ValueError("第 %d 行字段数为 %d（应为 7）: %s" % (n, len(parts), line[:80]))
        rows.append([x.strip() for x in parts])
    return rows


def build():
    out, errs = [], []
    seen_q = set()
    tmap = {"c": "choice", "m": "multi", "j": "judge", "e": "essay"}
    for i, (typ, ch, topic, question, opts, ans, exp) in enumerate(parse_rows(), 1):
        qid = "elq%03d" % i
        if typ not in tmap:
            errs.append("%s 题型非法: %s" % (qid, typ)); continue
        if not question or not exp:
            errs.append("%s 题干或解析为空" % qid)
        if question in seen_q:
            errs.append("%s 题干重复: %s" % (qid, question[:40]))
        seen_q.add(question)
        if topic.startswith("跨章") or topic.startswith("综合"):
            full_topic = "全书综合 · " + topic
        else:
            full_topic = "第%s章 %s" % (ch, topic)
        d = dict(id=qid, note=NOTE, topic=full_topic, question=question, type=tmap[typ])
        if typ == "e":
            d["answer"] = ans
            d["explanation"] = exp
        else:
            options = ["正确", "错误"] if typ == "j" else opts.split(";")
            if len(options) < 2 or len(options) != len(set(options)):
                errs.append("%s 选项数异常或重复: %s" % (qid, options))
            if typ in ("c", "j"):
                try:
                    a = int(ans)
                except ValueError:
                    errs.append("%s 答案非整数" % qid); a = -1
                if not (0 <= a < len(options)):
                    errs.append("%s 答案索引越界" % qid)
            else:
                try:
                    a = [int(x) for x in ans.split(",")]
                except ValueError:
                    errs.append("%s 多选答案格式错" % qid); a = []
                if len(a) < 2 or len(set(a)) != len(a) or any(x < 0 or x >= len(options) for x in a):
                    errs.append("%s 多选答案异常" % qid)
            d["options"] = options
            d["answer"] = a
            d["explanation"] = exp
        out.append(d)
    return out, errs


def main():
    questions, errs = build()
    if errs:
        print("校验失败:")
        for e in errs:
            print("  -", e)
        sys.exit(1)
    chapters = Counter(int(re.search(r"第(\d+)章", q["topic"]).group(1))
                       for q in questions if "第" in q["topic"] and "章" in q["topic"])
    missing = [c for c in range(1, 13) if chapters.get(c, 0) == 0]
    if missing:
        print("以下章节无题目:", missing); sys.exit(1)
    with open(OUT, encoding="utf-8") as f:
        data = json.load(f)
    data = [q for q in data if q.get("note") != NOTE]
    clash = {q["id"] for q in data} & {q["id"] for q in questions}
    if clash:
        print("ID 冲突:", clash); sys.exit(1)
    data.extend(questions)
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
        f.write("\n")
    print("校验通过 ✓  新增 %d 题，题库合计 %d 题" % (len(questions), len(data)))
    print("题型分布:", dict(Counter(q["type"] for q in questions)))
    print("章节分布:", dict(sorted(chapters.items())))
    print("输出:", OUT)


if __name__ == "__main__":
    main()
